'use client';

import {useCallback,useEffect,useMemo,useState} from 'react';
import {
 LayoutDashboard,Building2,Users,Wallet,Boxes,KeyRound,Webhook,Globe,LifeBuoy,Bell,Settings,
 BarChart3,LogOut,Menu,Plus,Check,X,Trash2,Copy,ArrowUpLeft,ShieldCheck,Clock,ChevronDown,
 CreditCard,Layers,Mail,Lock,ArrowLeft,ArrowRight,CheckCircle2,AlertCircle,Activity,Send,
 ExternalLink,Link2,FileText,RefreshCw,Zap,Calendar,Server,CheckCheck,ArrowLeftRight
} from 'lucide-react';

const nav=[
 ['overview','نمای کلی',LayoutDashboard],['workspaces','فضاهای کاری',Building2],['team','اعضای تیم',Users],
 ['products','محصولات',Boxes],['billing','اشتراک و مالی',Wallet],['analytics','آمار و مصرف',BarChart3],
 ['integrations','API و وب‌هوک',KeyRound],['domains','دامنه‌ها',Globe],['support','پشتیبانی',LifeBuoy],
 ['notifications','اعلان‌ها',Bell],['settings','تنظیمات',Settings]
];
const planOrder=['free','pro','business','custom'];
const roles={owner:'مالک',admin:'مدیر',manager:'مدیر تیم',member:'عضو',viewer:'مشاهده‌گر'};
const productIcons={crm:Users,projects:Layers,erp:Boxes,booking:Calendar,finance:Wallet,learning:FileText,analytics:BarChart3};
const iconBg={crm:'#e9edff',projects:'#f1ecff',erp:'#e8f5ef',booking:'#fff1e2',finance:'#e3f3fd',learning:'#fff0f0',analytics:'#f3ecff'};
const number=v=>new Intl.NumberFormat('fa-IR').format(Number(v||0));
const money=v=>Number(v)===0?'رایگان':number(v)+' تومان';
const fmtDate=d=>d?new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium'}).format(new Date(d)):'—';
function dateRelative(d){if(!d)return '—';const days=Math.floor((Date.now()-new Date(d).getTime())/864e5);return days===0?'امروز':days<0?'آینده':days===1?'دیروز':`${number(days)} روز پیش`}
const cls=(...xs)=>xs.filter(Boolean).join(' ');

function Logo({small=false}){return <div className="logo-wrap"><div className="logo-mark"><span>◈</span></div>{!small&&<div className="logo-copy"><strong>دایرا کلود</strong><small>زیرساخت نرم‌افزارهای SaaS</small></div>}</div>}
function Button({children,onClick,variant='primary',icon:Icon,disabled,type='button',className=''}) {return <button type={type} className={cls('btn','btn-'+variant,className)} disabled={disabled} onClick={onClick}>{children}{Icon&&<Icon size={16}/>}</button>}
function Status({value}){const good=['active','trialing','paid','resolved','verified','succeeded'];const bad=['failed','canceled','past_due'];return <span className={cls('status',good.includes(value)?'status-green':bad.includes(value)?'status-red':'status-amber')}><span className="status-dot"/>{({active:'فعال',trialing:'آزمایشی',pending:'در انتظار',paid:'پرداخت شده',void:'باطل',canceled:'لغوشده',open:'باز',resolved:'حل‌شده',paused:'متوقف',past_due:'سررسید گذشته',processing:'در حال ارسال'})[value]||value}</span>}
function Empty({icon:Icon=Layers,title,body,action}){return <div className="empty"><div className="empty-icon"><Icon size={24}/></div><h3>{title}</h3><p>{body}</p>{action}</div>}
function Section({title,desc,action,children,className=''}){return <section className={cls('panel',className)}><div className="panel-head"><div><h2>{title}</h2>{desc&&<p>{desc}</p>}</div>{action}</div>{children}</section>}
function Metric({label,value,detail,icon:Icon,tint='#eef1ff'}){return <article className="metric"><div className="metric-top"><span className="metric-icon" style={{background:tint}}><Icon size={20}/></span><ArrowUpLeft size={15} className="dim"/></div><div className="metric-value">{value}</div><div className="metric-label">{label}</div><div className="metric-sub">{detail}</div></article>}
function Progress({value,max,label}){const pct=Math.min(100,Math.round(Number(value||0)/Math.max(1,Number(max||1))*100));return <div className="progress-row"><div className="progress-title"><span>{label}</span><span>{number(value)} <span className="dim">از {number(max)}</span></span></div><div className="progress-track"><span style={{width:`${pct}%`}} className={pct>=90?'high':''}/></div></div>}
function Field({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Table({heads,rows,empty='موردی ثبت نشده است.'}){return <div className="table-wrap"><table><thead><tr>{heads.map((h,i)=><th key={i}>{h}</th>)}</tr></thead><tbody>{rows.length?rows.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>):<tr><td className="table-empty" colSpan={heads.length}>{empty}</td></tr>}</tbody></table></div>}

export default function Home(){
 const [data,setData]=useState(null),[loading,setLoading]=useState(true),[error,setError]=useState('');
 const [busy,setBusy]=useState(false),[screen,setScreen]=useState('overview'),[mobileMenu,setMobileMenu]=useState(false);
 const [authMode,setAuthMode]=useState('register'),[authForm,setAuthForm]=useState({name:'',email:'',password:'',confirm:''});
 const [modal,setModal]=useState(''),[fields,setFields]=useState({}),[revealed,setRevealed]=useState(null),[toast,setToast]=useState('');
 const [activeWorkspace,setActiveWorkspace]=useState(''),[adminData,setAdminData]=useState(null),[inviteToken,setInviteToken]=useState('');
 const [integrationTab,setIntegrationTab]=useState('keys'),[ticketDetail,setTicketDetail]=useState(null);
 const notify=useCallback(message=>{setToast(message);},[]);
 const load=useCallback(async(wid)=>{
  setLoading(true);setError('');
  try{const response=await fetch('/api/app'+(wid?'?workspace='+encodeURIComponent(wid):''),{cache:'no-store'});
   let body=await response.json();if(!response.ok)throw Error(body.error||'خطا در دریافت اطلاعات');
   if(!body.authenticated){
    const demo=await fetch('/api/demo'+(wid?'?workspace='+encodeURIComponent(wid):''),{cache:'no-store'});
    body=await demo.json();if(!demo.ok)throw Error(body.error||'خطا در دریافت اطلاعات نمایشی');
   }
   setData(body);if(body.workspace?.id)setActiveWorkspace(body.workspace.id);
  }catch(e){setError(e.message)}finally{setLoading(false)}
 },[]);
 useEffect(()=>{const qs=new URLSearchParams(window.location.search);const token=qs.get('invite');if(token)setInviteToken(token);const payment=qs.get('payment');if(payment){setToast(({paid:'پرداخت توسط درگاه تأیید شد.',cancelled:'پرداخت لغو شد.',failed:'تأیید پرداخت ناموفق بود.',unavailable:'درگاه پرداخت آماده نیست.'})[payment]||'وضعیت پرداخت مشخص نیست.');history.replaceState(null,'','/');}load();if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});},[load]);
 const post=async(action,payload={},opts={})=>{
  if(data?.demo){notify('در نسخه نمایشی، تغییرات ذخیره نمی‌شوند.');setModal('');return null;}
  setBusy(true);setError('');
  try {const r=await fetch('/api/app',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,workspaceId:activeWorkspace,...payload})});
   const body=await r.json();if(!r.ok)throw Error(body.error||'عملیات انجام نشد.');
   if(body.apiKey||body.webhookSecret||body.integrationToken||body.inviteUrl||body.dnsRecord)setRevealed(body);
   else notify(body.message||'تغییرات با موفقیت ثبت شد.');
   if(body.redirectUrl){window.location.assign(body.redirectUrl);return body;}
   if(opts.refresh!==false)await load(opts.select||body.workspaceId||activeWorkspace);
   if(opts.close!==false){setModal('');setFields({})}
   return body;
  }catch(e){setError(e.message);return null}finally{setBusy(false)}
 };
 const submitAuth=async(e)=>{
  e.preventDefault();if(authMode==='register'&&authForm.password!==authForm.confirm){setError('تکرار رمز عبور مطابقت ندارد.');return}
  await post(authMode==='register'?'register':'login',{name:authForm.name,email:authForm.email,password:authForm.password},{select:null});
 };
 const openModal=(name,initial={})=>{setModal(name);setFields(initial);setRevealed(null);setError('')};
 const login=data?.authenticated||data?.demo;
 const user=data?.user;
 const ws=data?.workspace;
 const sub=data?.subscription;
 const members=data?.team||[];
 const usage=data?.usage||[];
 const usedApi=usage.find(x=>x.feature==='api_calls')?.amount||0;
 const selectedCodes=new Set((data?.activeProducts||[]).map(x=>x.product_code));
 const canAdmin=['owner','admin'].includes(ws?.role);
 const canOwner=ws?.role==='owner';
 const navScreen=(v)=>{setScreen(v);setMobileMenu(false);setError('');setToast('');if(v==='admin'&&user?.is_platform_admin)fetch(data?.demo?'/api/demo?admin=1':'/api/admin').then(async x=>{const body=await x.json();if(!x.ok)throw Error(body.error||'خطای پنل');setAdminData(body)}).catch(x=>setError(x.message));};
 const adminPost=async(action,payload={})=>{if(data?.demo){notify('مدیریت مرکزی در نسخه دمو فقط برای مشاهده است.');return null;}setBusy(true);setError('');try{const r=await fetch('/api/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...payload})});const b=await r.json();if(!r.ok)throw Error(b.error||'عملیات ناموفق بود');const d=await fetch('/api/admin',{cache:'no-store'});if(!d.ok)throw Error('بروزرسانی پنل ناموفق بود');setAdminData(await d.json());notify('تغییرات ثبت شد.');return b;}catch(e){setError(e.message);return null}finally{setBusy(false)}};
 const hasPaidPrice=Number(sub?.price_monthly)>0;
 const totalInvoices=(data?.invoices||[]).length;
 const activePlan=data?.plans?.find(x=>x.code===sub?.plan_code);
 const switchProduct=(code,enabled)=>post('toggle-product',{productCode:code,enabled});
 const exportReport=(kind)=>data?.demo?notify('خروجی واقعی فقط در فضای کاری شخصی قابل دریافت است.'):window.open(`/api/export?workspace=${encodeURIComponent(activeWorkspace)}&kind=${encodeURIComponent(kind)}`,'_blank','noopener,noreferrer');
 const copy=async(text)=>{try{await navigator.clipboard.writeText(text);notify('کپی شد.')}catch{notify('کپی خودکار ممکن نشد.')}};
 const confirmAction=(action,payload,text)=>{if(data?.demo){notify('این قابلیت در نسخه نمایشی فقط قابل مشاهده است.');return;}if(window.confirm(text))post(action,payload)};
 const activeTicket=async(t)=>{try{const r=await fetch(data?.demo?`/api/demo?workspace=${encodeURIComponent(activeWorkspace)}&ticket=${encodeURIComponent(t.id)}`:`/api/app?workspace=${encodeURIComponent(activeWorkspace)}&ticket=${encodeURIComponent(t.id)}`);const x=await r.json();if(x.ticket){setTicketDetail(x.ticket);openModal('ticket-detail',{id:t.id})}else notify(x.error||'اطلاعات تیکت قابل دریافت نیست.')}catch{notify('خطا در بارگذاری درخواست.')}};

 const content=()=>{
 if(!ws)return <Section title="فضاهای کاری" desc="اولین فضای کاری خود را ایجاد کنید."><Empty title="فضای کاری ندارید" body="یک فضای کاری مستقل ایجاد کنید تا مدیریت تیم و اشتراک شروع شود." action={<Button icon={Plus} onClick={()=>openModal('workspace-create')}>ایجاد فضای کاری</Button>}/></Section>;
 if(screen==='overview')return <>
  <div className="headline"><div><span className="eyebrow"><span className="eyebrow-dot"/> وضعیت سیستم در یک نگاه</span><h1>سلام، {user.name.split(' ')[0]} <span className="wave">✳</span></h1><p>مدیریت سرویس‌ها، اعضا و اشتراک <strong>{ws.name}</strong> از یک مکان.</p></div><Button variant="secondary" icon={Plus} onClick={()=>openModal('workspace-create')}>فضای کاری جدید</Button></div>
  <div className="metrics-grid"><Metric icon={Layers} label="پلن فعال" value={sub?.plan_name||'—'} detail={sub?.trial_ends_at?'پایان آزمایشی '+fmtDate(sub.trial_ends_at):sub?.status==='active'?'اشتراک فعال':'وضعیت اشتراک'}/><Metric icon={Users} tint="#e8f5ef" label="اعضای تیم" value={number(members.length)} detail={`از ${number(sub?.seat_limit)} جایگاه`}/><Metric icon={Activity} tint="#fff2e5" label="درخواست‌های API این ماه" value={number(usedApi)} detail={`از ${number(sub?.api_limit)} درخواست`}/><Metric icon={Boxes} tint="#f0ecff" label="محصولات فعال" value={number(selectedCodes.size)} detail={`از ${number(sub?.product_limit)} محصول`}/></div>
  <div className="split-7-5"><Section title="وضعیت مصرف" desc="مصرف واقعی فضای کاری، براساس ثبت رویداد در API" action={<button className="link-btn" onClick={()=>navScreen('analytics')}>مشاهده گزارش <ArrowLeft size={15}/></button>}><div className="progress-list"><Progress label="درخواست‌های API" value={usedApi} max={sub?.api_limit}/><Progress label="اعضای فعال" value={members.length} max={sub?.seat_limit}/><Progress label="محصولات فعال" value={selectedCodes.size} max={sub?.product_limit}/></div><div className="info-line"><ShieldCheck size={17}/><span>مصرف‌ها از دیتابیس محاسبه می‌شوند، نه اطلاعات نمایشی.</span></div></Section>
  <Section title="اشتراک فعلی" desc="اطلاعات صورتحساب و دسترسی"><div className="subscription-card"><div className="subscription-top"><div><small>پلن کنونی</small><strong>{sub?.plan_name}</strong></div><Status value={sub?.status}/></div><div className="subscription-bottom"><span>هزینه ماهانه نمونه</span><strong>{money(sub?.price_monthly)}</strong></div></div><Button variant="secondary" className="full" onClick={()=>navScreen('billing')}>مدیریت اشتراک <ArrowLeft size={16}/></Button></Section></div>
  <div className="split-7-5"><Section title="محصولات فضای کاری" desc="ماژول‌هایی که دسترسی به آن‌ها فعال شده است" action={<button className="link-btn" onClick={()=>navScreen('products')}>مدیریت <ArrowLeft size={15}/></button>}><div className="product-mini-grid">{(data?.products||[]).slice(0,6).map(p=>{const Icon=productIcons[p.code];return <button key={p.code} className="product-mini" onClick={()=>navScreen('products')}><span style={{background:iconBg[p.code]}}><Icon size={19}/></span><div><strong>{p.name}</strong><small>{selectedCodes.has(p.code)?'فعال':'غیرفعال'}</small></div></button>})}</div></Section>
  <Section title="آخرین رویدادها" desc="ثبت فعالیت‌های مدیریتی و امنیتی">{(data?.activity||[]).length?<div className="activity-list">{data.activity.slice(0,5).map(x=><div className="activity-row" key={x.id}><div className="timeline-dot"/><div><strong>{eventName(x.action)}</strong><small>{fmtDate(x.created_at)}</small></div></div>)}</div>:<Empty icon={Activity} title="هنوز رویدادی نیست" body="تغییرات فضای کاری اینجا ثبت می‌شوند."/>}</Section></div>
 </>;
 if(screen==='workspaces')return <><PageHead title="فضاهای کاری" desc="چند کسب‌وکار با داده‌ها، اعضا و اشتراک‌های مستقل" action={<Button icon={Plus} onClick={()=>openModal('workspace-create')}>ایجاد فضای کاری</Button>}/><div className="cards-grid">{(data.workspaces||[]).map(w=><article className={cls('workspace-card',w.id===ws.id&&'selected')} key={w.id}><div className="ws-avatar">{w.name[0]}</div><div className="ws-data"><h3>{w.name}</h3><span>{w.slug}.your-domain.tld</span><div className="ws-badges"><span className="pill">{roles[w.role]}</span>{w.id===ws.id&&<span className="pill blue">فضای جاری</span>}</div></div><Button variant="secondary" onClick={()=>{setActiveWorkspace(w.id);load(w.id)}}>ورود به فضا <ArrowLeft size={15}/></Button></article>)}</div></>;
 if(screen==='team')return <><PageHead title='مدیریت اعضای تیم' desc='دعوت همکاران و تنظیم سطح دسترسی برای هر فضای کاری' action={canAdmin&&<div className='admin-controls'><Button variant='secondary' onClick={()=>exportReport('team')}>خروجی CSV</Button><Button icon={Plus} onClick={()=>openModal('invite')}>دعوت عضو جدید</Button></div>}/><div className="summary-strip"><Users size={21}/><span>{number(members.length)} عضو فعال از ظرفیت {number(sub?.seat_limit)} نفر</span><span className="ml-auto pill">{ws.name}</span></div><Section title="اعضای فعال"><Table heads={['عضو','نقش و دسترسی','عضویت','عملیات']} rows={members.map(m=>[<div className="person"><span className="person-avatar">{m.name[0]}</span><div><strong>{m.name}</strong><small>{m.email}</small></div></div>,<span className="pill">{roles[m.role]}</span>,fmtDate(m.created_at),canAdmin&&m.role!=='owner'&&m.user_id!==user.id?<div className="action-inline"><select className="table-select" value={m.role} onChange={e=>post('update-role',{userId:m.user_id,role:e.target.value})}>{Object.entries(roles).filter(([k])=>k!=='owner'&&roleRank(k)<roleRank(ws.role)).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><button className="icon-btn danger" title="حذف عضو" onClick={()=>confirmAction('remove-member',{userId:m.user_id},'این عضو از فضای کاری حذف شود؟')}><Trash2 size={16}/></button></div>:'—'])}/></Section><Section title="دعوت‌های در انتظار" desc="لینک دعوت هفت روز اعتبار دارد"><Table heads={['ایمیل','نقش','تاریخ ارسال','انقضا','عملیات']} rows={(data.invitations||[]).map(m=>[m.email,roles[m.role],fmtDate(m.created_at),fmtDate(m.expires_at),canAdmin?<button className='icon-btn danger' aria-label='لغو دعوت' onClick={()=>confirmAction('revoke-invite',{id:m.id},'دعوت‌نامه لغو شود؟')}><Trash2 size={16}/></button>:'—'])}/></Section></>;
 if(screen==='products')return <><PageHead title="محصولات و ماژول‌ها" desc="زیرساخت اشتراکی مشترک برای مجموعه نرم‌افزارهای مدیریتی"/><div className="summary-strip"><Boxes size={20}/><span>{number(selectedCodes.size)} محصول از {number(sub?.product_limit)} محصول مجاز فعال است.</span><button className="link-btn ml-auto" onClick={()=>navScreen('billing')}>افزایش ظرفیت <ArrowLeft size={15}/></button></div><div className="module-grid">{(data.products||[]).map(p=>{const Icon=productIcons[p.code]||Boxes;const on=selectedCodes.has(p.code);return <article className="module" key={p.code}><div className="module-icon" style={{background:iconBg[p.code]}}><Icon size={24}/></div><h3>{p.name}</h3><p>{p.desc}</p><div className="module-bottom"><span className={cls('pill',on&&'green')}>{on?'مجوز فعال':'غیرفعال'}</span><button className={cls('toggle',on&&'on')} role="switch" aria-checked={on} disabled={!canAdmin||busy} onClick={()=>switchProduct(p.code,!on)}><span/></button></div>{on&&canAdmin&&<Button variant='ghost' onClick={()=>post('create-integration-token',{productCode:p.code},{refresh:false})}>ساخت کد اتصال یک‌بارمصرف</Button>}</article>})}</div><p className="note"><AlertCircle size={16}/> فعال‌سازی در این بخش، مجوز دسترسی به محصول است؛ برای اتصال واقعی CRM، ERP و سایر محصولات باید آن سرویس‌ها به API یکپارچه متصل شوند.</p></>;
 if(screen==='billing')return <><PageHead title="اشتراک و صورتحساب" desc="پلن‌ها، دوره آزمایشی، پیش‌فاکتورها و تاریخچه مالی"/><div className="billing-hero"><div><span className="sub-eyebrow">اشتراک فضای کاری</span><h2>{sub?.plan_name} <Status value={sub?.status}/></h2><p>{sub?.status==='trialing'?'دوره آزمایشی تا '+fmtDate(sub.trial_ends_at):'پایان دوره: '+fmtDate(sub?.current_period_ends_at)}</p></div><div><span>هزینه ماهانه نمونه</span><strong>{money(sub?.price_monthly)}</strong></div></div><h3 className="section-title">انتخاب پلن مناسب</h3><div className="plan-grid">{[...data.plans].sort((a,b)=>planOrder.indexOf(a.code)-planOrder.indexOf(b.code)).map(p=><article className={cls('plan-card',p.code===sub?.plan_code&&'current',p.code==='pro'&&'featured')} key={p.code}><div className="plan-card-top"><span className="pill">{p.code===sub?.plan_code?'پلن جاری':p.code==='pro'?'پیشنهادی':'پلن'}</span><h3>{p.name}</h3><p className="plan-price">{p.code==='custom'?'توافقی':money(p.price_monthly)}<small>{p.code!=='custom'&&Number(p.price_monthly)>0?' / ماه':''}</small></p></div><div className="plan-features"><span><Check size={16}/> {number(p.seat_limit)} کاربر</span><span><Check size={16}/> {number(p.product_limit)} محصول</span><span><Check size={16}/> {number(p.api_limit)} درخواست API ماهانه</span><span><Check size={16}/> {number(p.storage_mb)} مگابایت سهمیه اسمی</span><span><Check size={16}/> {p.features.webhooks?'وب‌هوک و یکپارچه‌سازی':'API پایه'}</span></div><Button variant={p.code===sub?.plan_code?'ghost':p.code==='pro'?'primary':'secondary'} disabled={!canOwner||p.code===sub?.plan_code||busy||p.code==='custom'} onClick={()=>post('plan-request',{planCode:p.code})} className="full">{p.code===sub?.plan_code?'پلن فعال':p.code==='custom'?'تماس با پشتیبانی':p.code==='free'?'انتخاب رایگان':'دریافت پیش‌فاکتور'}</Button></article>)}</div><p className="note"><AlertCircle size={16}/> قیمت‌های فعلی صرفاً مقادیر نمونه و قابل تنظیم‌اند. {data.providers?.payment?'پرداخت فقط پس از تأیید سرورِ درگاه، اشتراک را فعال می‌کند.':'درگاه هنوز پیکربندی نشده است؛ پیش‌فاکتور پرداخت‌نشده به معنی فعال‌شدن پلن نیست.'}</p><Section title="فاکتورها" desc={`${number(totalInvoices)} فاکتور برای فضای کاری`} action={canOwner&&<div className='admin-controls'><Button variant='secondary' onClick={()=>exportReport('invoices')}>دانلود CSV</Button><Button variant='secondary' onClick={()=>openModal('coupon')}>اعمال کد تخفیف</Button></div>}><Table heads={['شماره','پلن','مبلغ','وضعیت','تاریخ','پرداخت']} rows={(data.invoices||[]).map(i=>[<code className='ltr'>{i.id.slice(0,8)}</code>,i.plan_code,money(Number(i.amount)-Number(i.discount_amount)),<Status value={i.status}/>,fmtDate(i.created_at),i.status==='pending'&&canOwner?<Button variant='secondary' disabled={!data.providers?.payment||busy} onClick={()=>post('pay-invoice',{id:i.id},{refresh:false})}>پرداخت امن</Button>:'—'])}/></Section><div className="billing-bottom"><div><strong>اعتبار حساب: {money(data.credit)}</strong><small>اعتبار بدون ثبت پرداخت واقعی افزایش داده نمی‌شود.</small></div>{canOwner&&!sub?.cancel_at_period_end&&sub?.plan_code!=='free'&&<Button variant="secondary" onClick={()=>confirmAction('cancel-subscription',{},'اشتراک در پایان دوره فعلی لغو شود؟')}>لغو در پایان دوره</Button>}{sub?.cancel_at_period_end&&canOwner&&<Button variant='secondary' onClick={()=>post('resume-subscription')}>انصراف از لغو اشتراک</Button>}</div></>;
 if(screen==='analytics')return <><PageHead title='مصرف و تحلیل' desc='گزارش سهمیه‌ها و مصرف فضای کاری انتخاب‌شده' action={canAdmin&&<Button variant='secondary' onClick={()=>exportReport('usage')}>دریافت گزارش CSV</Button>}/><div className="metrics-grid"><Metric icon={Activity} label="API این ماه" value={number(usedApi)} detail="درخواست محاسبه‌شده"/><Metric icon={Users} label="اعضای تیم" value={number(members.length)} detail="اعضای فعال"/><Metric icon={Boxes} label="محصولات" value={number(selectedCodes.size)} detail="مجوزهای فعال"/><Metric icon={Webhook} label="وب‌هوک‌های ناموفق" value={number(data.failedWebhooks)} detail="ارسال‌های ناموفق"/></div><Section title="گزارش سهمیه‌ها" desc="جمع مصرف از اول ماه میلادی جاری"><Progress value={usedApi} max={sub?.api_limit} label="سهمیه درخواست API"/><div className="usage-list">{usage.filter(x=>x.feature!=='api_calls').length?usage.filter(x=>x.feature!=='api_calls').map(x=><div key={x.feature} className="usage-item"><span>{x.feature}</span><strong>{number(x.amount)}</strong></div>):<Empty icon={Activity} title="داده مصرفی ثبت نشده" body="بعد از اتصال سرویس‌ها به API ثبت مصرف، آمار اینجا نمایش داده می‌شود."/>}</div></Section><Section title="شاخص‌های اشتراک"><div className="info-grid"><Info name="پلن" value={sub?.plan_name}/><Info name="وضعیت" value={<Status value={sub?.status}/>}/><Info name="ظرفیت تیم" value={number(sub?.seat_limit)}/><Info name="سهمیه API" value={number(sub?.api_limit)}/></div></Section></>;
 if(screen==='integrations')return <><PageHead title="یکپارچه‌سازی و توسعه‌دهندگان" desc="کلیدهای دسترسی و دریافت رخدادهای سیستم"/><div className="tabs"><button className={cls(integrationTab==='keys'&&'active')} onClick={()=>setIntegrationTab('keys')}><KeyRound size={17}/> کلیدهای API</button><button className={cls(integrationTab==='hooks'&&'active')} onClick={()=>setIntegrationTab('hooks')}><Webhook size={17}/> وب‌هوک‌ها</button></div>{integrationTab==='keys'?<><Section title="کلیدهای API" desc="هر کلید فقط در زمان ساخت یک بار قابل مشاهده است." action={canAdmin&&<Button icon={Plus} onClick={()=>openModal('api')}>ساخت کلید</Button>}><Table heads={['نام کلید','پیشوند','دسترسی','آخرین استفاده','عملیات']} rows={(data.apiKeys||[]).map(k=>[k.label,<code className="ltr">{k.key_prefix}…</code>,(k.scopes||[]).join(', '),fmtDate(k.last_used_at),canAdmin?<button className="icon-btn danger" onClick={()=>confirmAction('revoke-api-key',{id:k.id},'کلید API لغو شود؟')}><Trash2 size={16}/></button>:'—'])} empty="هنوز کلیدی ایجاد نشده است."/></Section><div className="code-example"><div><span>نمونه ثبت مصرف</span><code>POST /api/v1/usage</code></div><pre dir="ltr">{`curl -X POST /api/v1/usage \\\n  -H 'Authorization: Bearer <API_KEY>' \\\n  -H 'Idempotency-Key: req-001' \\\n  -H 'Content-Type: application/json' \\\n  -d '{"feature":"crm_contacts","amount":1}'`}</pre></div></>:<><Section title="وب‌هوک‌های ثبت‌شده" desc="ارسال رویداد با امضای HMAC-SHA256، صف و تلاش مجدد" action={canAdmin&&<Button icon={Plus} onClick={()=>openModal('webhook')}>وب‌هوک جدید</Button>}><Table heads={['عنوان','آدرس','وضعیت','عملیات']} rows={(data.webhooks||[]).map(h=>[h.label,<code className="short-url ltr">{h.url}</code>,<span className={cls('pill',h.enabled&&'green')}>{h.enabled?'فعال':'غیرفعال'}</span>,canAdmin?<div className="action-inline"><button className='icon-btn' title={h.enabled?'غیرفعال کردن':'فعال کردن'} onClick={()=>post('toggle-webhook',{id:h.id,enabled:!h.enabled})}>{h.enabled?<X size={16}/>:<Check size={16}/>}</button><button className="icon-btn" title="تست ارسال" onClick={()=>post('test-webhook',{id:h.id})}><Send size={16}/></button><button className="icon-btn danger" title="حذف" onClick={()=>confirmAction('remove-webhook',{id:h.id},'وب‌هوک حذف شود؟')}><Trash2 size={16}/></button></div>:'—'])} empty="هیچ وب‌هوکی ثبت نشده است."/></Section><p className="note"><Server size={17}/> پردازش ارسال، نیازمند اجرای Worker روی سرور یا زمان‌بندی جداگانه است؛ در اجرای Vercel بدون Worker رویدادها در صف می‌مانند.</p></>}</>;
 if(screen==='domains')return <><PageHead title="دامنه‌ها و آدرس‌ها" desc="تنظیم زیردامنه و اثبات مالکیت دامنه اختصاصی" action={canOwner&&<Button icon={Plus} onClick={()=>openModal('domain')}>افزودن دامنه</Button>}/><Section title="زیردامنه فضای کاری" desc="آدرس پیشنهادی، پس از تنظیم DNS و پراکسی مشترک"><div className="domain-inline"><div className="domain-icon"><Globe size={22}/></div><div><strong dir="ltr">{ws.slug}.your-domain.tld</strong><span>نیازمند راه‌اندازی wildcard DNS در دامنه اصلی</span></div><span className="pill">آماده اتصال</span></div></Section><Section title="دامنه‌های اختصاصی"><Table heads={['دامنه','تأیید مالکیت','رکورد TXT','عملیات']} rows={(data.domains||[]).map(d=>[<strong className="ltr">{d.hostname}</strong>,d.verified_at?<span className="pill green">تأیید شده</span>:<span className="pill">در انتظار DNS</span>,<button className="copy-record" onClick={()=>copy(d.verification_token)}>کپی رکورد <Copy size={14}/></button>,!d.verified_at&&canOwner?<Button variant="secondary" onClick={()=>post('verify-domain',{id:d.id})}>بررسی DNS</Button>:'—'])}/></Section><p className="note"><AlertCircle size={16}/> تأیید TXT فقط مالکیت دامنه را اثبات می‌کند؛ اتصال نهایی دامنه به سرویس Hosting/Reverse Proxy باید جداگانه انجام شود.</p></>;
 if(screen==='support')return <><PageHead title="پشتیبانی و درخواست‌ها" desc="تیکت‌های فضای کاری شما" action={<Button icon={Plus} onClick={()=>openModal('ticket')}>درخواست جدید</Button>}/><Section title="درخواست‌های پشتیبانی"><Table heads={['موضوع','اولویت','وضعیت','تاریخ','مشاهده']} rows={(data.tickets||[]).map(t=>[<strong>{t.subject}</strong>,({low:'کم',normal:'عادی',high:'زیاد'})[t.priority],<Status value={t.status}/>,fmtDate(t.created_at),<button className="link-btn" onClick={()=>activeTicket(t)}>جزئیات <ArrowLeft size={15}/></button>])}/></Section><div className="hint-box"><LifeBuoy size={21}/><div><strong>مرکز راهنمای دایرا کلود</strong><p>درخواست‌ها در دیتابیس ذخیره می‌شوند. برای پاسخ‌گویی تیم پشتیبانی، مدیریت مرکزی نیز باید به جریان تیکت‌ها متصل شود.</p></div></div></>;
 if(screen==='notifications')return <><PageHead title="اعلان‌ها و اطلاعیه‌ها" desc="رویدادهای فضای کاری و پیام‌های سراسری"/><Section title="اعلان‌های شما">{(data.notifications||[]).length?<div className="notification-list">{data.notifications.map(n=><div key={n.id} className={cls('notification-row',!n.read_at&&'unread')}><Bell size={20}/><div><strong>{n.title}</strong><p>{n.body}</p><small>{fmtDate(n.created_at)}</small></div>{!n.read_at&&<button className="icon-btn" title="خوانده شد" onClick={()=>post('notification-read',{id:n.id})}><CheckCheck size={19}/></button>}</div>)}</div>:<Empty icon={Bell} title="اعلان جدیدی ندارید" body="اعلان‌های پرداخت، اشتراک و ظرفیت پس از فعال‌سازی جریان رویدادها نمایش داده می‌شوند."/>}</Section><Section title="اطلاعیه‌های عمومی">{(data.announcements||[]).length?data.announcements.map(a=><div className="announcement" key={a.id}><strong>{a.title}</strong><p>{a.body}</p><small>{fmtDate(a.published_at)}</small></div>):<Empty icon={Bell} title="اطلاعیه‌ای منتشر نشده است" body="اطلاعیه‌های پلتفرم اینجا نمایش داده می‌شوند."/>}</Section></>;
 if(screen==='settings')return <><PageHead title="تنظیمات فضای کاری" desc="تنظیم مشخصات و مشاهده وضعیت امنیت و زیرساخت"/><div className="settings-grid"><Section title="مشخصات کسب‌وکار"><div className="settings-item"><div><strong>نام فضای کاری</strong><small>{ws.name}</small></div>{canAdmin&&<Button variant="secondary" onClick={()=>openModal('rename',{name:ws.name})}>ویرایش</Button>}</div><div className="settings-item"><div><strong>شناسه فضای کاری</strong><small className="ltr">{ws.id}</small></div><button className="icon-btn" onClick={()=>copy(ws.id)}><Copy size={18}/></button></div><div className="settings-item"><div><strong>نقش شما</strong><small>{roles[ws.role]}</small></div><ShieldCheck size={18}/></div></Section><Section title="امنیت و داده‌ها"><div className="security-row"><ShieldCheck/><div><strong>کوکی نشست HttpOnly</strong><small>محافظت‌شده در مرورگر</small></div><CheckCircle2 size={18} className="good"/></div><div className="security-row"><Lock/><div><strong>رمز عبور رمزنگاری‌شده</strong><small>scrypt به‌همراه salt مجزا</small></div><CheckCircle2 size={18} className="good"/></div><div className="security-row"><Server/><div><strong>پایگاه داده PostgreSQL</strong><small>قابل مهاجرت با SQL و Docker</small></div><CheckCircle2 size={18} className='good'/></div></Section><AccountSettings user={user} providers={data.providers} onPost={post} notify={notify}/></div></>;
 if(screen==='admin'&&user?.is_platform_admin)return <AdminConsole data={adminData} onAction={adminPost} busy={busy}/>;
 return null;
 };

 if(loading&&!data)return <div className="boot"><Logo/><div className="spinner"/><p>در حال اتصال به فضای کاری…</p>{error&&<button onClick={()=>load()}>تلاش مجدد</button>}</div>;
 if(!login)return <div className="auth-shell"><aside className="auth-art"><div className="auth-art-head"><Logo/></div><div className="auth-art-content"><div className="auth-chip"><Zap size={15}/> زیرساختی برای ایده‌های بزرگ</div><h1>همه چیز برای ساخت<br/><em>یک SaaS واقعی.</em></h1><p>از کاربر و فضای کاری تا اشتراک، صورتحساب و API — تمام بخش‌های اصلی در یک هسته مستقل.</p><div className="auth-points"><span><CheckCircle2 size={17}/> چندفضای‌کاری مستقل</span><span><CheckCircle2 size={17}/> کنترل نقش‌ها و مجوزها</span><span><CheckCircle2 size={17}/> قابل انتقال به سرور اختصاصی</span></div></div><div className="auth-art-footer">DAIRA CLOUD <span>·</span> 2026</div><div className="auth-deco a"/><div className="auth-deco b"/></aside><main className="auth-main"><div className="mobile-auth-logo"><Logo/></div><div className="auth-container"><div className="auth-title"><span className="auth-welcome">به دایرا کلود خوش آمدید</span><h2>{authMode==='register'?'فضای کاری‌ات را بساز':'ورود به حساب کاربری'}</h2><p>{authMode==='register'?'برای شروع، مشخصات حساب را وارد کنید.':'برای ادامه مدیریت، وارد حساب خود شوید.'}</p></div><div className="auth-switch"><button className={authMode==='register'?'active':''} onClick={()=>{setAuthMode('register');setError('')}}>ثبت‌نام</button><button className={authMode==='login'?'active':''} onClick={()=>{setAuthMode('login');setError('')}}>ورود</button>{data?.providers?.sms&&<button className={authMode==='sms'?'active':''} onClick={()=>{setAuthMode('sms');setError('')}}>ورود پیامکی</button>}</div>{authMode==='sms'?<SmsLogin onDone={()=>load()}/>:<form className="auth-form" onSubmit={submitAuth}>{authMode==='register'&&<Field label="نام و نام خانوادگی"><div className="input-wrap"><Users size={18}/><input required minLength={2} autoComplete="name" placeholder="مثلاً محمد رضایی" value={authForm.name} onChange={e=>setAuthForm({...authForm,name:e.target.value})}/></div></Field>}<Field label="ایمیل"><div className="input-wrap"><Mail size={18}/><input required type="email" autoComplete="email" dir="ltr" placeholder="you@example.com" value={authForm.email} onChange={e=>setAuthForm({...authForm,email:e.target.value})}/></div></Field><Field label="رمز عبور"><div className="input-wrap"><Lock size={18}/><input required type="password" minLength={authMode==='register'?10:1} autoComplete={authMode==='register'?'new-password':'current-password'} placeholder="حداقل ۱۰ کاراکتر" value={authForm.password} onChange={e=>setAuthForm({...authForm,password:e.target.value})}/></div></Field>{authMode==='register'&&<Field label="تکرار رمز عبور"><div className="input-wrap"><Lock size={18}/><input required type="password" minLength={10} autoComplete="new-password" placeholder="رمز را دوباره وارد کنید" value={authForm.confirm} onChange={e=>setAuthForm({...authForm,confirm:e.target.value})}/></div></Field>}{error&&<div className="alert error"><AlertCircle size={17}/>{error}</div>}<Button type="submit" disabled={busy} className="full" icon={ArrowLeft}>{busy?'در حال پردازش…':authMode==='register'?'ساخت حساب و شروع ۱۴ روز آزمایشی':'ورود به داشبورد'}</Button></form>}{authMode==='login'&&<a href='/reset' className='auth-reset-link'>فراموشی رمز عبور؟</a>}<div className="auth-footnote"><ShieldCheck size={17}/> اطلاعات شما در فضای کاری مستقل نگهداری می‌شوند.</div></div></main></div>;
 return <div className="dashboard-shell"><aside className={cls('sidebar',mobileMenu&&'mobile-open')}><div className="sidebar-header"><Logo/><button className="close-menu icon-btn" onClick={()=>setMobileMenu(false)}><X size={20}/></button></div><button className="current-ws" onClick={()=>navScreen('workspaces')}><div className="current-ws-icon">{ws?.name?.[0]||'د'}</div><div><strong>{ws?.name||'فضای کاری'}</strong><small>{roles[ws?.role]||'عضو'}</small></div><ChevronDown size={16}/></button><div className="sidebar-label">فضای کاری</div><nav className="side-nav">{nav.map(([key,label,Icon])=><button key={key} className={cls('side-link',screen===key&&'active')} onClick={()=>navScreen(key)}><Icon size={19} strokeWidth={1.9}/><span>{label}</span>{key==='notifications'&&(data?.notifications||[]).some(n=>!n.read_at)&&<span className="side-unread"/>}</button>)}</nav>{user?.is_platform_admin&&<><div className="sidebar-label">مدیریت کل</div><nav className="side-nav"><button className={cls('side-link',screen==='admin'&&'active')} onClick={()=>navScreen('admin')}><ShieldCheck size={19}/> مدیریت مرکزی</button></nav></>}<div className="sidebar-bottom"><div className="sidebar-help"><span className="help-icon"><LifeBuoy size={19}/></span><strong>نیاز به راهنمایی دارید؟</strong><small>از بخش پشتیبانی پیام بفرستید.</small><button onClick={()=>navScreen('support')}>ارتباط با پشتیبانی <ArrowLeft size={14}/></button></div>{data?.demo?<div className="user-profile demo-user"><span className="person-avatar">د</span><span><strong>مشاهده نسخه آزمایشی</strong><small>بدون ورود به حساب</small></span><ShieldCheck size={18}/></div>:<button className="user-profile" onClick={()=>post('logout',{},{select:null})}><span className="person-avatar">{user?.name?.[0]}</span><span><strong>{user?.name}</strong><small>{user?.email}</small></span><LogOut size={18}/></button>}</div></aside>{mobileMenu&&<button className="mobile-backdrop" onClick={()=>setMobileMenu(false)}/>}<div className="main-column"><header className="topbar"><div className="topbar-first"><button className="mobile-trigger icon-btn" onClick={()=>setMobileMenu(true)}><Menu size={22}/></button><span className="breadcrumb">فضای کاری</span><span className="crumb-sep">/</span><strong>{screen==='admin'?'مدیریت مرکزی':nav.find(x=>x[0]===screen)?.[1]||'نمای کلی'}</strong></div><div className="topbar-actions"><span className="topbar-date"><Clock size={16}/> {fmtDate(new Date())}</span><button className="topbar-icon" title="اعلان‌ها" onClick={()=>navScreen('notifications')}><Bell size={19}/>{(data?.notifications||[]).some(n=>!n.read_at)&&<i/>}</button><button className="topbar-avatar" onClick={()=>navScreen('settings')}>{user?.name?.[0]}</button></div></header><main className="content"><div className="page-container">{data?.demo&&<div className="demo-notice"><span className="demo-notice-dot"/><div><strong>نسخه نمایشی عمومی — بدون نیاز به ورود</strong><span>تمام اعداد و اطلاعات ساختگی هستند؛ تغییرات ذخیره نمی‌شوند.</span></div><span className="demo-notice-pill">فقط مشاهده</span></div>}{error&&<div className="alert error"><AlertCircle size={17}/>{error}<button onClick={()=>setError('')}><X size={16}/></button></div>}{toast&&<div className="alert success"><CheckCircle2 size={17}/>{toast}<button onClick={()=>setToast('')}><X size={16}/></button></div>}{inviteToken&&<div className="invite-banner"><div><Mail size={19}/><span>دعوت‌نامه برای عضویت در فضای کاری دریافت شده است.</span></div><Button disabled={busy} onClick={async()=>{const v=await post('accept-invite',{token:inviteToken});if(v){setInviteToken('');history.replaceState(null,'','/');load(v.workspaceId)}}}>پذیرش دعوت</Button></div>}{loading?<div className="content-loading"><div className="spinner"/> در حال بروزرسانی اطلاعات…</div>:content()}<footer className="dashboard-footer"><span>© ۲۰۲۶ دایرا کلود</span><span>زیرساخت چندمشتری · نسخه اولیه عملیاتی</span></footer></div></main></div>{modal&&<div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)setModal('')}}><div className="dialog" role="dialog" aria-modal="true"><div className="dialog-top"><div><strong>{modalTitles[modal]||'عملیات'}</strong><p>{modalDescriptions[modal]||'لطفاً اطلاعات را وارد کنید.'}</p></div><button className="icon-btn" onClick={()=>{setModal('');setError('')}}><X size={20}/></button></div><form onSubmit={e=>{e.preventDefault();if(modal==='workspace-create')post('create-workspace',{name:fields.name},{select:null});if(modal==='rename')post('workspace-rename',{name:fields.name});if(modal==='invite')post('invite-member',{email:fields.email,role:fields.role||'member'});if(modal==='api')post('create-api-key',{label:fields.label});if(modal==='webhook')post('add-webhook',{label:fields.label,url:fields.url});if(modal==='domain')post('add-domain',{hostname:fields.hostname});if(modal==='coupon')post('redeem-coupon',{code:fields.code});if(modal==='ticket')post('ticket-create',{subject:fields.subject,message:fields.message});if(modal==='ticket-detail')post('ticket-reply',{id:fields.id,message:fields.message}).then(x=>{if(x)setTicketDetail(null)})}}><div className="dialog-body">{['workspace-create','rename'].includes(modal)&&<Field label="نام فضای کاری"><input autoFocus required minLength={2} placeholder="نام کسب‌وکار" value={fields.name||''} onChange={e=>setFields({...fields,name:e.target.value})}/></Field>}{modal==='invite'&&<><Field label="ایمیل همکار"><input required type="email" dir="ltr" placeholder="teammate@example.com" value={fields.email||''} onChange={e=>setFields({...fields,email:e.target.value})}/></Field><Field label="نقش"><select value={fields.role||'member'} onChange={e=>setFields({...fields,role:e.target.value})}>{Object.entries(roles).filter(([k])=>k!=='owner'&&roleRank(k)<roleRank(ws?.role)).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></Field><p className="field-hint">لینک دعوت اختصاصی تولید می‌شود و می‌توانید برای همکار ارسال کنید.</p></>}{modal==='api'&&<Field label="نام کلید"><input required placeholder="مثلاً اتصال به CRM" value={fields.label||''} onChange={e=>setFields({...fields,label:e.target.value})}/></Field>}{modal==='webhook'&&<><Field label="عنوان"><input placeholder="مثلاً مدیریت سفارش‌ها" value={fields.label||''} onChange={e=>setFields({...fields,label:e.target.value})}/></Field><Field label="نشانی HTTPS"><input required type="url" dir="ltr" placeholder="https://your-service.com/webhooks" value={fields.url||''} onChange={e=>setFields({...fields,url:e.target.value})}/></Field></>}{modal==='domain'&&<Field label="دامنه اختصاصی"><input required dir="ltr" placeholder="app.example.com" value={fields.hostname||''} onChange={e=>setFields({...fields,hostname:e.target.value})}/></Field>}{modal==='coupon'&&<Field label="کد تخفیف"><input required dir="ltr" placeholder="COUPON" value={fields.code||''} onChange={e=>setFields({...fields,code:e.target.value})}/></Field>}{modal==='ticket'&&<><Field label="موضوع درخواست"><input required placeholder="موضوع" value={fields.subject||''} onChange={e=>setFields({...fields,subject:e.target.value})}/></Field><Field label="توضیحات"><textarea required rows={5} placeholder="مشکل یا درخواست را توضیح دهید…" value={fields.message||''} onChange={e=>setFields({...fields,message:e.target.value})}/></Field></>}{modal==='ticket-detail'&&<><div className="ticket-chat">{ticketDetail?.messages?.map(m=><div className="ticket-chat-message" key={m.id}><strong>{m.name}</strong><p>{m.message}</p><small>{fmtDate(m.created_at)}</small></div>)}</div><Field label="پاسخ جدید"><textarea required rows={4} placeholder="متن پیام…" value={fields.message||''} onChange={e=>setFields({...fields,message:e.target.value})}/></Field></>}{error&&<div className="alert error"><AlertCircle size={17}/>{error}</div>}</div><div className="dialog-actions"><Button variant="secondary" onClick={()=>setModal('')}>انصراف</Button><Button type="submit" disabled={busy} icon={Check}>{busy?'در حال انجام…':'ثبت و ادامه'}</Button></div></form></div></div>}{revealed&&<div className="modal-backdrop"><div className="dialog"><div className="dialog-top"><div><strong>اطلاعات ساخته‌شده</strong><p>مقدار محرمانه را در محل امن نگهداری کنید.</p></div><button className="icon-btn" onClick={()=>setRevealed(null)}><X size={20}/></button></div><div className="dialog-body"><div className="alert info"><ShieldCheck size={18}/> {revealed.webhookSecret||revealed.apiKey||revealed.integrationToken?'این مقدار فقط یک بار نمایش داده می‌شود.': 'اطلاعات را کپی کنید.'}</div>{Object.entries({apiKey:revealed.apiKey,webhookSecret:revealed.webhookSecret,integrationToken:revealed.integrationToken,inviteUrl:revealed.inviteUrl,dnsRecord:revealed.dnsRecord,dnsValue:revealed.dnsValue}).filter(([,v])=>v).map(([k,v])=><div className="secret-field" key={k}><small>{({apiKey:'کلید API',webhookSecret:'رمز امضای وب‌هوک',integrationToken:'کد اتصال یک‌بارمصرف (۲ دقیقه)',inviteUrl:'لینک دعوت',dnsRecord:'نام رکورد TXT',dnsValue:'مقدار TXT'})[k]}</small><div><code dir="ltr">{v}</code><button className="icon-btn" onClick={()=>copy(v)}><Copy size={17}/></button></div></div>)}</div><div className="dialog-actions"><Button onClick={()=>setRevealed(null)}>بستن</Button></div></div></div>}</div>;
}
function Info({name,value}){return <div className="info"><span>{name}</span><strong>{value}</strong></div>}
function PageHead({title,desc,action}){return <div className="page-head"><div><h1>{title}</h1><p>{desc}</p></div>{action}</div>}
function roleRank(role){return ({viewer:0,member:1,manager:2,admin:3,owner:4})[role]??0}
function eventName(action){return ({'workspace.created':'ایجاد فضای کاری','workspace.renamed':'ویرایش نام فضای کاری','member.invited':'ارسال دعوت‌نامه','member.joined':'پیوستن عضو جدید','member.role_changed':'تغییر سطح دسترسی','member.removed':'حذف عضو','apikey.created':'ایجاد کلید API','apikey.revoked':'لغو کلید API','webhook.created':'افزودن وب‌هوک','webhook.deleted':'حذف وب‌هوک','subscription.plan_requested':'درخواست تغییر پلن','subscription.downgraded':'تغییر به پلن رایگان','subscription.cancel_scheduled':'ثبت لغو اشتراک','product.toggled':'تغییر مجوز محصول','domain.added':'ثبت دامنه','domain.dns_verified':'تأیید دامنه','ticket.created':'ایجاد تیکت','coupon.redeemed':'اعمال کد تخفیف'})[action]||action}
const modalTitles={'workspace-create':'فضای کاری جدید',rename:'ویرایش نام فضای کاری',invite:'دعوت عضو جدید',api:'ایجاد کلید API',webhook:'افزودن وب‌هوک',domain:'ثبت دامنه اختصاصی',coupon:'اعمال کد تخفیف',ticket:'درخواست پشتیبانی جدید','ticket-detail':'گفت‌وگوی پشتیبانی'};
const modalDescriptions={'workspace-create':'هر فضای کاری داده‌ها و اعضای مستقلی خواهد داشت.',invite:'برای اعضای تیم لینک دعوت تولید کنید.',api:'کلید را تنها یک بار خواهید دید.',webhook:'رخدادها با امضای دیجیتال ارسال خواهند شد.',domain:'مالکیت دامنه را با رکورد TXT اثبات کنید.',coupon:'کد بر آخرین پیش‌فاکتور پرداخت‌نشده اعمال می‌شود.'};

function SmsLogin({onDone}){
 const [phone,setPhone]=useState(''),[code,setCode]=useState(''),[step,setStep]=useState(0),[busy,setBusy]=useState(false),[message,setMessage]=useState('');
 async function submit(event){event.preventDefault();setBusy(true);setMessage('');try{
  const action=step?'confirm-login':'request-login';
  const response=await fetch('/api/sms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,phone,code})});
  const body=await response.json();if(!response.ok)throw Error(body.error||'عملیات انجام نشد.');
  if(step){onDone();return;}setStep(1);setMessage(body.message||'در صورت وجود حساب، کد ارسال شد.');
 }catch(error){setMessage(error.message);}finally{setBusy(false)}}
 return <form className="auth-form" onSubmit={submit}>
  <Field label="شماره تلفن همراه"><input type="tel" dir="ltr" required value={phone} onChange={e=>setPhone(e.target.value)} placeholder="09123456789" autoComplete="tel"/></Field>
  {step===1&&<Field label="کد شش رقمی"><input type="text" dir="ltr" required inputMode="numeric" pattern="[0-9]{6}" maxLength={6} value={code} onChange={e=>setCode(e.target.value)} placeholder="123456" autoComplete="one-time-code"/></Field>}
  {message&&<div className="alert info">{message}</div>}
  <Button className="full" type="submit" disabled={busy} icon={ArrowLeft}>{busy?'در حال پردازش…':step?'تأیید کد و ورود':'ارسال کد یک‌بارمصرف'}</Button>
  {step===1&&<Button variant="secondary" onClick={()=>{setStep(0);setCode('');setMessage('')}}>تغییر شماره یا درخواست مجدد</Button>}
 </form>
}
function PhoneSettings({providers,user}){
 const [phone,setPhone]=useState(user?.phone||''),[code,setCode]=useState(''),[step,setStep]=useState(0),[busy,setBusy]=useState(false),[message,setMessage]=useState('');
 async function submit(event){event.preventDefault();setBusy(true);setMessage('');try{
  const response=await fetch('/api/sms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:step?'confirm-phone':'request-phone-verification',phone,code})});
  const result=await response.json();if(!response.ok)throw Error(result.error||'عملیات انجام نشد.');
  if(step){setStep(2);setMessage('شماره موبایل تأیید شد.');}else{setStep(1);setMessage('کد یک‌بارمصرف ارسال شد.');}
 }catch(error){setMessage(error.message);}finally{setBusy(false)}}
 return <form className="account-settings" onSubmit={submit}>
  <h3>ورود و تأیید شماره موبایل</h3>
  <Field label="شماره تلفن"><input required type="tel" dir="ltr" autoComplete="tel" value={phone} disabled={!providers?.sms||step===2} placeholder="09123456789" onChange={e=>setPhone(e.target.value)}/></Field>
  {step===1&&<Field label="کد پیامک"><input required dir="ltr" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} value={code} onChange={e=>setCode(e.target.value)}/></Field>}
  {message&&<div className="alert info">{message}</div>}
  {step===2?<span className="status status-green">تأیید شد</span>:<Button type="submit" variant="secondary" disabled={!providers?.sms||busy} icon={Check}>{!providers?.sms?'نیازمند اتصال سرویس پیامک':busy?'در حال پردازش…':step?'تأیید کد':'ارسال کد تأیید'}</Button>}
 </form>
}
function AccountSettings({user,providers,onPost}){
 const [name,setName]=useState(user?.name||'');
 const [currentPassword,setCurrentPassword]=useState('');
 const [newPassword,setNewPassword]=useState('');
 const [repeatPassword,setRepeatPassword]=useState('');
 const [status,setStatus]=useState('');
 const [verifying,setVerifying]=useState(false);
 async function verification(){setVerifying(true);setStatus('');try{const r=await fetch('/api/account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'send-verification'})});const data=await r.json();if(!r.ok)throw Error(data.error||'عملیات ناموفق بود');setStatus(data.message)}catch(e){setStatus(e.message)}finally{setVerifying(false)}}
 return <Section title="حساب کاربری و امنیت" desc="اطلاعات کاربری و نشست‌های فعال">
  <form className="account-settings" onSubmit={async e=>{e.preventDefault();await onPost('profile-update',{name});}}>
   <Field label="نام نمایشی"><input minLength={2} maxLength={75} required value={name} onChange={e=>setName(e.target.value)}/></Field>
   <Field label="ایمیل"><input readOnly value={user.email} dir="ltr"/></Field>
   <div className="settings-item"><span>{user.email_verified_at?'ایمیل تأییدشده':'ایمیل هنوز تأیید نشده است'}</span>{!user.email_verified_at&&<button className="btn btn-secondary" disabled={!providers?.email||verifying} type="button" onClick={verification}>{verifying?'در حال ارسال…':providers?.email?'ارسال لینک تأیید':'نیازمند اتصال ایمیل'}</button>}</div>
   {status&&<div className="alert info">{status}</div>}
   <Button type="submit" variant="secondary" icon={Check}>ذخیره نام</Button>
  </form>
  <form className="account-settings" onSubmit={async e=>{e.preventDefault();if(newPassword!==repeatPassword){setStatus('تکرار رمز مطابقت ندارد.');return;}const out=await onPost('change-password',{currentPassword,newPassword});if(out){setCurrentPassword('');setNewPassword('');setRepeatPassword('')}}}>
   <h3>تغییر رمز عبور</h3>
   <Field label="رمز فعلی"><input type="password" required autoComplete="current-password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)}/></Field>
   <Field label="رمز جدید (حداقل ۱۰ کاراکتر)"><input type="password" required minLength={10} maxLength={128} autoComplete="new-password" value={newPassword} onChange={e=>setNewPassword(e.target.value)}/></Field>
   <Field label="تکرار رمز جدید"><input type="password" required minLength={10} maxLength={128} autoComplete="new-password" value={repeatPassword} onChange={e=>setRepeatPassword(e.target.value)}/></Field>
   <Button type="submit" variant="secondary" icon={Lock}>ذخیره رمز جدید</Button>
  </form>
  <PhoneSettings user={user} providers={providers}/>
  <div className="settings-item"><div><strong>خروج از تمام دستگاه‌ها</strong><small>تمام نشست‌ها فوراً باطل می‌شوند.</small></div><Button variant="secondary" onClick={()=>window.confirm('از همه دستگاه‌ها خارج شوید؟')&&onPost('logout-all')}>خروج از همه نشست‌ها</Button></div>
 </Section>
}
function AdminConsole({data,onAction,busy}){
 const [code,setCode]=useState(''),[percent,setPercent]=useState('10'),[max,setMax]=useState('100');
 const [announcementTitle,setAnnouncementTitle]=useState(''),[announcementBody,setAnnouncementBody]=useState('');
 const [selectedTicket,setSelectedTicket]=useState(''),[ticketMessage,setTicketMessage]=useState('');
 const [editingPlan,setEditingPlan]=useState(''),[planDraft,setPlanDraft]=useState(null);
 if(!data)return <div className="content-loading"><div className="spinner"/>در حال دریافت اطلاعات مدیریت مرکزی…</div>;
 const planCols=['price_monthly','seat_limit','api_limit','storage_mb','product_limit'];
 const labels={price_monthly:'قیمت ماهانه (تومان)',seat_limit:'کاربران',api_limit:'درخواست API',storage_mb:'حجم (MB)',product_limit:'محصولات'};
 return <>
  <PageHead title="مدیریت مرکزی پلتفرم" desc="نمای کلی مشترکان، صورت‌حساب‌ها، تیکت‌ها و تنظیمات اشتراک"/>
  <div className="metrics-grid">
   <Metric icon={Building2} label="فضاهای کاری" value={number(data.totals?.workspaces)}/>
   <Metric icon={Users} label="حساب‌های ثبت‌شده" value={number(data.totals?.users)}/>
   <Metric icon={CreditCard} label="اشتراک‌های فعال/آزمایشی" value={number(data.totals?.active_subscriptions)}/>
   <Metric icon={Wallet} label="درآمد ماهانه تکرارشونده" value={money(data.totals?.mrr)} detail="فقط اشتراک‌های فعال پولی"/>
   <Metric icon={Activity} label="درآمد تأییدشده" value={money(data.totals?.paid_revenue)} detail="مجموع صورتحساب‌های پرداخت‌شده"/>
   <Metric icon={LifeBuoy} label="تیکت‌های باز" value={number(data.totals?.open_tickets)}/>
  </div>
  <Section title="فضاهای کاری و مشترکان" desc="عملیات تعلیق فقط از طریق مدیر کل ثبت می‌شود.">
   <Table heads={['نام','شناسه','پلن','وضعیت','اعضا','عملیات']} rows={(data.recent||[]).map(w=>[
    <strong>{w.name}</strong>,<code dir="ltr">{w.slug}</code>,w.plan_code,<Status value={w.status}/>,number(w.members),
    <Button variant="secondary" disabled={busy} onClick={()=>{const action=w.status==='paused'?'workspace-resume':'workspace-suspend';if(window.confirm('وضعیت اشتراک این فضای کاری تغییر کند؟'))onAction(action,{workspaceId:w.id})}}>{w.status==='paused'?'رفع تعلیق':'تعلیق'}</Button>
   ])}/>
  </Section>
  <Section title="تیکت‌های تمام فضاهای کاری" desc="پاسخ‌ها در تاریخچه مکالمه مشتری ذخیره می‌شوند.">
   <Table heads={['فضا','موضوع','وضعیت','آخرین تغییر','عملیات']} rows={(data.tickets||[]).map(t=>[
    t.workspace_name,<strong>{t.subject}</strong>,<Status value={t.status}/>,fmtDate(t.updated_at),<div className="admin-controls"><button className="link-btn" onClick={()=>{setSelectedTicket(t.id);setTicketMessage('')}}>پاسخ</button><select disabled={busy} value={t.status} onChange={e=>onAction('ticket-status',{ticketId:t.id,status:e.target.value})}><option value="open">باز</option><option value="pending">در انتظار</option><option value="resolved">حل‌شده</option></select></div>
   ])}/>
   {selectedTicket&&<form className="admin-controls" onSubmit={async e=>{e.preventDefault();const res=await onAction('ticket-reply',{ticketId:selectedTicket,message:ticketMessage});if(res){setSelectedTicket('');setTicketMessage('')}}}><textarea required minLength={2} value={ticketMessage} placeholder="پاسخ کارشناس به درخواست انتخاب‌شده…" onChange={e=>setTicketMessage(e.target.value)}/><Button type="submit" disabled={busy} icon={Send}>ارسال پاسخ</Button><Button variant="secondary" onClick={()=>setSelectedTicket('')}>انصراف</Button></form>}
  </Section>
  <Section title="کوپن‌ها و کدهای تخفیف">
   <form className="admin-controls" onSubmit={async e=>{e.preventDefault();const res=await onAction('coupon-create',{code,percentOff:Number(percent),maxRedemptions:Number(max)});if(res)setCode('')}}>
    <input required minLength={3} maxLength={50} placeholder="کد تخفیف" dir="ltr" value={code} onChange={e=>setCode(e.target.value.toUpperCase())}/>
    <label>درصد <input type="number" min="1" max="100" value={percent} onChange={e=>setPercent(e.target.value)}/></label>
    <label>تعداد مصرف <input type="number" min="1" value={max} onChange={e=>setMax(e.target.value)}/></label>
    <Button type="submit" disabled={busy} icon={Plus}>ساخت کوپن</Button>
   </form>
   <Table heads={['کد','تخفیف','مصرف','وضعیت','عملیات']} rows={(data.coupons||[]).map(c=>[
    <code dir="ltr">{c.code}</code>,`${number(c.percent_off)}٪`,`${number(c.redemptions)} / ${number(c.max_redemptions)}`,c.active?'فعال':'غیرفعال',<Button variant="secondary" disabled={busy} onClick={()=>onAction('coupon-toggle',{code:c.code,active:!c.active})}>{c.active?'غیرفعال‌سازی':'فعال‌سازی'}</Button>
   ])}/>
  </Section>
  <Section title="اطلاعیه‌های عمومی">
   <form className="admin-form" onSubmit={async e=>{e.preventDefault();const res=await onAction('announcement-publish',{title:announcementTitle,body:announcementBody});if(res){setAnnouncementTitle('');setAnnouncementBody('')}}}>
    <Field label="عنوان"><input required maxLength={120} value={announcementTitle} onChange={e=>setAnnouncementTitle(e.target.value)}/></Field>
    <Field label="متن اطلاعیه"><textarea required rows={3} maxLength={4000} value={announcementBody} onChange={e=>setAnnouncementBody(e.target.value)}/></Field>
    <Button type="submit" disabled={busy} icon={Send}>انتشار اطلاعیه</Button>
   </form>
   <Table heads={['عنوان','متن','تاریخ']} rows={(data.announcements||[]).map(a=>[a.title,<span className="text-truncated">{a.body}</span>,fmtDate(a.published_at)])}/>
  </Section>
  <Section title="قیمت‌گذاری و ظرفیت پلن‌ها" desc="تغییرات فقط بر درخواست‌های جدید و ظرفیت‌های جاری اثر می‌گذارد؛ فاکتورهای صادرشده تغییر نمی‌کنند.">
   <Table heads={['پلن','ماهانه','کاربران','API','فضا','محصولات','عملیات']} rows={(data.planCatalog||[]).map(p=>[
    <strong>{p.name}</strong>,money(p.price_monthly),number(p.seat_limit),number(p.api_limit),`${number(p.storage_mb)} MB`,number(p.product_limit),<Button variant="secondary" onClick={()=>{setEditingPlan(p.code);setPlanDraft({...p,features:{...p.features}})}}>ویرایش</Button>
   ])}/>
   {planDraft&&<form className="admin-form" onSubmit={async e=>{e.preventDefault();const res=await onAction('plan-update',planDraft);if(res){setEditingPlan('');setPlanDraft(null)}}}>
    <h3>ویرایش پلن {planDraft.name} ({editingPlan})</h3>
    <div className="admin-controls">{planCols.map(k=><label key={k}>{labels[k]}<input type="number" min={k==='price_monthly'?0:1} value={planDraft[k]} onChange={e=>setPlanDraft({...planDraft,[k]:e.target.value})}/></label>)}</div>
    <div className="admin-controls">{['api','webhooks','custom_domain'].map(k=><label key={k}><input type="checkbox" checked={!!planDraft.features[k]} onChange={e=>setPlanDraft({...planDraft,features:{...planDraft.features,[k]:e.target.checked}})}/>{({api:'API',webhooks:'وب‌هوک',custom_domain:'دامنه اختصاصی'})[k]}</label>)}</div>
    <div className="admin-controls"><Button type="submit" disabled={busy} icon={Check}>ذخیره پلن</Button><Button variant="secondary" onClick={()=>setPlanDraft(null)}>انصراف</Button></div>
   </form>}
  </Section>
  <Section title="آخرین صورتحساب‌ها" desc="وضعیت پرداخت فقط با تأیید مستقل درگاه تغییر می‌کند.">
   <Table heads={['فضای کاری','پلن','مبلغ نهایی','وضعیت','تاریخ']} rows={(data.invoices||[]).map(i=>[
    i.workspace_name,i.plan_code,money(Number(i.amount)-Number(i.discount_amount)),<Status value={i.status}/>,fmtDate(i.created_at)
   ])}/>
  </Section>
  <Section title="روند درآمد تأییدشده"><Table heads={['ماه','مبلغ']} rows={(data.revenueHistory||[]).map(x=>[fmtDate(x.month),money(x.revenue)])}/></Section>
 </>;
}
